// DeleteUniqueIndexCache 删除索引存在的缓存
func (m *MembershipBenefitTypeRepo) DeleteIndexCache(ctx context.Context, data ...*ai_boilerplate_model.MembershipBenefitType) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, m.cache.Key(CacheMembershipBenefitTypeByConditionPrefix))
	keys = append(keys, m.cache.Key(CacheMembershipBenefitTypeUnscopedByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[m.cache.Key(CacheMembershipBenefitTypeByIDPrefix, item.ID)] = struct{}{}
			KeyMap[m.cache.Key(CacheMembershipBenefitTypeUnscopedByIDPrefix, item.ID)] = struct{}{}
			KeyMap[m.cache.Key(CacheMembershipBenefitTypeByBenefitKeyPrefix, item.BenefitKey)] = struct{}{}
			KeyMap[m.cache.Key(CacheMembershipBenefitTypeUnscopedByBenefitKeyPrefix, item.BenefitKey)] = struct{}{}
			KeyMap[m.cache.Key(CacheMembershipBenefitTypeBySortPrefix, item.Sort)] = struct{}{}
			KeyMap[m.cache.Key(CacheMembershipBenefitTypeUnscopedBySortPrefix, item.Sort)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := m.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
